using namespace moon;
int main(){try{std::size_t caseIndex=0;for(const auto& c:outlineOracle){timeline::Surface surface;surface.width=c.width;surface.height=c.height;surface.pixels=c.pixels;OutlineSampling settings;settings.thickness=c.thickness;settings.position=c.position;settings.kernel=c.kernel;settings.directions=c.directions;settings.background=c.background;settings.sourceColor=c.source;const auto samples=outlineSamples(surface,c.width,c.height,c.selection,settings);if(samples.size()*2!=c.expected.size())throw std::runtime_error("sample size case "+std::to_string(caseIndex));for(std::size_t i=0;i<samples.size();++i)if(samples[i].index!=c.expected[i*2]||samples[i].reference!=c.expected[i*2+1])throw std::runtime_error("sample order/color case "+std::to_string(caseIndex));// Sparse native storage must produce the same world-space samples.
 timeline::Surface sparse; sparse.width=c.width+2;sparse.height=c.height+2;sparse.offsetX=sparse.offsetY=-1;sparse.pixels.resize(std::size_t(sparse.width)*sparse.height);for(int y=0;y<c.height;++y)for(int x=0;x<c.width;++x)sparse.pixels[std::size_t(y+1)*sparse.width+x+1]=c.pixels[std::size_t(y)*c.width+x];const auto sparseSamples=outlineSamples(sparse,c.width,c.height,c.selection,settings);if(sparseSamples.size()!=samples.size())throw std::runtime_error("sparse sample size");for(std::size_t i=0;i<samples.size();++i)if(sparseSamples[i].index!=samples[i].index||sparseSamples[i].reference!=samples[i].reference)throw std::runtime_error("sparse world mapping");++caseIndex;}for(const auto& c:outlineBoundaryOracle){timeline::Surface surface;surface.width=c.width;surface.height=c.height;surface.pixels=c.pixels;OutlineSampling settings;settings.thickness=c.thickness;settings.kernel=c.kernel;settings.directions=c.directions;const auto samples=outlineBoundarySamples(surface,c.width,c.height,c.selection,settings);if(samples.size()*2!=c.expected.size())throw std::runtime_error("boundary size");for(std::size_t i=0;i<samples.size();++i)if(samples[i].index!=c.expected[i*2]||samples[i].reference!=c.expected[i*2+1])throw std::runtime_error("boundary sample");}
 for(const auto& c:outlineColorOracle)if(outlineStrokeColor(c.color,c.reference,c.smart,c.darkness,c.follow)!=c.expected)throw std::runtime_error("stroke color");
 std::cout<<caseIndex<<" exact legacy sample cases passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
